"""Curated offline catalog.

Every title here is real. Source identifiers (Wikipedia page, TVmaze id, AniList id,
Open Library work + cover id) were checked against the live APIs, so posters and
ratings resolve to the correct record. Mood, intensity and ending tags are editorial
judgements; descriptions are short, spoiler-free premise lines written for MOODFLIX.

Runtimes: movies = total minutes, series = typical episode length. Books = page count
of a common edition (approximate).
"""

MOODS = ['happy', 'romantic', 'sad', 'chaotic', 'relaxed', 'main-character', 'existential',
         'excited', 'cozy', 'mystery', 'motivated']


def _m(id, title, year, genres, moods, intensity, ending, minutes, description, tags, wiki, tmdb_id=None):
    return dict(id=id, title=title, year=year, kind='movie', genres=genres, moods=moods, intensity=intensity,
                ending=ending, minutes=minutes, description=description, tags=tags, wiki=wiki, tmdb_id=tmdb_id)


def _am(id, title, year, genres, moods, intensity, ending, minutes, description, tags, anilist_id):
    return dict(id=id, title=title, year=year, kind='anime_movie', genres=genres, moods=moods, intensity=intensity,
                ending=ending, minutes=minutes, description=description, tags=tags, anilist_id=anilist_id)


def _s(id, title, year, genres, moods, intensity, ending, minutes, description, tags, tvmaze_id, tmdb_id=None):
    return dict(id=id, title=title, year=year, kind='series', genres=genres, moods=moods, intensity=intensity,
                ending=ending, minutes=minutes, description=description, tags=tags, tvmaze_id=tvmaze_id, tmdb_id=tmdb_id)


def _as(id, title, year, genres, moods, intensity, ending, description, tags, anilist_id, minutes=24):
    return dict(id=id, title=title, year=year, kind='anime_series', genres=genres, moods=moods, intensity=intensity,
                ending=ending, minutes=minutes, description=description, tags=tags, anilist_id=anilist_id)


def _b(id, title, year, author, genres, moods, intensity, ending, pages, description, tags, ol_work, ol_cover):
    return dict(id=id, title=title, year=year, kind='book', author=author, genres=genres, moods=moods,
                intensity=intensity, ending=ending, pages=pages, description=description, tags=tags,
                ol_work=ol_work, ol_cover=ol_cover)


